import React from 'react';
import { Star, User, Calendar } from 'lucide-react';

const ReviewsList = ({ reviews, title, showAverage = true }) => {
  const averageRating = reviews.length > 0
    ? (reviews.reduce((sum, review) => sum + review.rating, 0) / reviews.length).toFixed(1)
    : 0;

  const renderStars = (rating) => {
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            className={`h-4 w-4 ${
              star <= rating
                ? 'text-yellow-400 fill-current'
                : 'text-gray-300'
            }`}
          />
        ))}
      </div>
    );
  };

  return (
    <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-md p-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-gray-800 dark:text-white">
          {title}
        </h3>
        {showAverage && reviews.length > 0 && (
          <div className="flex items-center gap-2 bg-mountain-green/10 text-mountain-green px-3 py-1 rounded-full">
            <Star className="h-4 w-4 fill-current" />
            <span className="font-semibold">{averageRating}</span>
            <span className="text-sm">({reviews.length} review{reviews.length !== 1 ? 's' : ''})</span>
          </div>
        )}
      </div>

      {reviews.length === 0 ? (
        <div className="text-center py-8">
          <User className="h-12 w-12 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 dark:text-gray-300">No reviews yet</p>
        </div>
      ) : (
        <div className="space-y-4">
          {reviews.map((review) => (
            <div key={review.id} className="border border-gray-200 dark:border-gray-700 rounded-xl p-4">
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-mountain-green/10 rounded-full flex items-center justify-center">
                    <User className="h-5 w-5 text-mountain-green" />
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      {renderStars(review.rating)}
                      <span className="text-sm font-medium text-gray-600 dark:text-gray-300">
                        {review.rating}/5
                      </span>
                    </div>
                    <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mt-1">
                      <Calendar className="h-3 w-3" />
                      {new Date(review.date).toLocaleDateString()}
                    </div>
                  </div>
                </div>
                {review.verified && (
                  <span className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded-full font-medium">
                    Verified
                  </span>
                )}
              </div>

              <p className="text-gray-700 dark:text-gray-200 leading-relaxed">
                {review.comment}
              </p>

              {review.reviewerType && (
                <div className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                  Review by {review.reviewerType === 'tenant' ? 'Tenant' : 'Landlord'}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ReviewsList;
