import React, { useState, useRef } from 'react';
import { motion } from 'framer-motion';
import { Upload, FileText, CheckCircle, XCircle, Clock, AlertTriangle, Shield, Eye, Download } from 'lucide-react';

const PartnerVerification = ({ property, onVerificationComplete }) => {
  const [documents, setDocuments] = useState([
    {
      id: 1,
      type: 'business_permit',
      name: 'Business Permit',
      required: true,
      uploaded: false,
      file: null,
      status: 'pending',
      verified: false,
      expiryDate: null
    },
    {
      id: 2,
      type: 'valid_id',
      name: 'Valid ID',
      required: true,
      uploaded: false,
      file: null,
      status: 'pending',
      verified: false,
      expiryDate: null
    },
    {
      id: 3,
      type: 'property_ownership',
      name: 'Property Ownership Documents',
      required: true,
      uploaded: false,
      file: null,
      status: 'pending',
      verified: false,
      expiryDate: null
    },
    {
      id: 4,
      type: 'tax_clearance',
      name: 'Tax Clearance Certificate',
      required: false,
      uploaded: false,
      file: null,
      status: 'pending',
      verified: false,
      expiryDate: null
    }
  ]);

  const [verificationStatus, setVerificationStatus] = useState('pending');
  const [lguResponse, setLguResponse] = useState(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const fileInputRefs = useRef({});

  const handleFileUpload = (documentId, event) => {
    const file = event.target.files[0];
    if (file) {
      setDocuments(prev => prev.map(doc =>
        doc.id === documentId
          ? { ...doc, file, uploaded: true, status: 'uploaded' }
          : doc
      ));
    }
  };

  const removeFile = (documentId) => {
    setDocuments(prev => prev.map(doc =>
      doc.id === documentId
        ? { ...doc, file: null, uploaded: false, status: 'pending' }
        : doc
    ));
  };

  const submitForVerification = async () => {
    const requiredDocs = documents.filter(doc => doc.required);
    const allRequiredUploaded = requiredDocs.every(doc => doc.uploaded);

    if (!allRequiredUploaded) {
      alert('Please upload all required documents before submitting.');
      return;
    }

    setIsSubmitting(true);
    setVerificationStatus('submitting');

    try {
      // Simulate LGU API call
      const response = await simulateLGUVerification(documents);
      setLguResponse(response);

      if (response.success) {
        setVerificationStatus('verified');
        setDocuments(prev => prev.map(doc => ({
          ...doc,
          verified: true,
          status: 'verified'
        })));

        // Call completion callback
        if (onVerificationComplete) {
          onVerificationComplete({
            propertyId: property.id,
            verified: true,
            lguVerifiedBy: response.verifiedBy,
            lguVerifiedAt: response.verifiedAt,
            blockchainHash: response.blockchainHash
          });
        }
      } else {
        setVerificationStatus('rejected');
        setDocuments(prev => prev.map(doc => ({
          ...doc,
          status: response.rejectedDocuments.includes(doc.type) ? 'rejected' : doc.status
        })));
      }
    } catch (error) {
      console.error('Verification failed:', error);
      setVerificationStatus('error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // Simulate LGU API verification
  const simulateLGUVerification = async (docs) => {
    return new Promise((resolve) => {
      setTimeout(() => {
        // Simulate random verification result
        const success = Math.random() > 0.3; // 70% success rate

        if (success) {
          resolve({
            success: true,
            verifiedBy: 'Baguio City LGU',
            verifiedAt: new Date().toISOString(),
            blockchainHash: '0x' + Math.random().toString(16).substr(2, 64),
            message: 'All documents verified successfully. Property is now officially verified.'
          });
        } else {
          resolve({
            success: false,
            rejectedDocuments: ['business_permit'],
            message: 'Business permit verification failed. Please check expiry date and authenticity.',
            verifiedBy: 'Baguio City LGU',
            verifiedAt: new Date().toISOString()
          });
        }
      }, 3000);
    });
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'verified':
        return <CheckCircle className="h-5 w-5 text-green-500" />;
      case 'rejected':
        return <XCircle className="h-5 w-5 text-red-500" />;
      case 'uploaded':
        return <Clock className="h-5 w-5 text-yellow-500" />;
      default:
        return <Clock className="h-5 w-5 text-gray-400" />;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'verified':
        return 'text-green-600 bg-green-50 border-green-200';
      case 'rejected':
        return 'text-red-600 bg-red-50 border-red-200';
      case 'uploaded':
        return 'text-yellow-600 bg-yellow-50 border-yellow-200';
      default:
        return 'text-gray-600 bg-gray-50 border-gray-200';
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="bg-white dark:bg-gray-800 rounded-2xl shadow-md p-6"
    >
      <div className="flex items-center gap-3 mb-6">
        <Shield className="h-6 w-6 text-mountain-green" />
        <div>
          <h3 className="text-xl font-semibold text-gray-800 dark:text-white">
            Partner Verification System
          </h3>
          <p className="text-sm text-gray-600 dark:text-gray-300">
            LGU/HEI API Integration for Property Verification
          </p>
        </div>
      </div>

      {/* Property Info */}
      <div className="bg-gray-50 dark:bg-gray-700 rounded-xl p-4 mb-6">
        <h4 className="font-medium text-gray-800 dark:text-white mb-2">Property Details</h4>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
          <div>
            <span className="text-gray-600 dark:text-gray-300">Property:</span>
            <span className="ml-2 font-medium text-gray-800 dark:text-white">{property.title}</span>
          </div>
          <div>
            <span className="text-gray-600 dark:text-gray-300">Location:</span>
            <span className="ml-2 font-medium text-gray-800 dark:text-white">{property.location}</span>
          </div>
          <div>
            <span className="text-gray-600 dark:text-gray-300">Owner:</span>
            <span className="ml-2 font-medium text-gray-800 dark:text-white">{property.owner}</span>
          </div>
          <div>
            <span className="text-gray-600 dark:text-gray-300">Type:</span>
            <span className="ml-2 font-medium text-gray-800 dark:text-white">{property.type}</span>
          </div>
        </div>
      </div>

      {/* Document Upload Section */}
      <div className="space-y-4 mb-6">
        <h4 className="font-medium text-gray-800 dark:text-white flex items-center gap-2">
          <FileText className="h-5 w-5" />
          Required Documents
        </h4>

        {documents.map((doc) => (
          <div key={doc.id} className={`border rounded-xl p-4 ${getStatusColor(doc.status)}`}>
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-3">
                {getStatusIcon(doc.status)}
                <div>
                  <h5 className="font-medium text-gray-800 dark:text-white">
                    {doc.name}
                    {doc.required && <span className="text-red-500 ml-1">*</span>}
                  </h5>
                  <p className="text-sm text-gray-600 dark:text-gray-300">
                    {doc.required ? 'Required' : 'Optional'}
                  </p>
                </div>
              </div>

              {doc.uploaded && doc.file && (
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => window.open(URL.createObjectURL(doc.file), '_blank')}
                    className="flex items-center gap-1 text-blue-600 hover:text-blue-800 text-sm"
                  >
                    <Eye className="h-4 w-4" />
                    View
                  </button>
                  <button
                    onClick={() => removeFile(doc.id)}
                    className="flex items-center gap-1 text-red-600 hover:text-red-800 text-sm"
                  >
                    <XCircle className="h-4 w-4" />
                    Remove
                  </button>
                </div>
              )}
            </div>

            {!doc.uploaded ? (
              <div>
                <input
                  ref={el => fileInputRefs.current[doc.id] = el}
                  type="file"
                  accept=".pdf,.jpg,.jpeg,.png"
                  onChange={(e) => handleFileUpload(doc.id, e)}
                  className="hidden"
                  id={`file-${doc.id}`}
                />
                <label
                  htmlFor={`file-${doc.id}`}
                  className="flex items-center justify-center gap-2 py-3 px-4 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg cursor-pointer hover:border-mountain-green transition-colors"
                >
                  <Upload className="h-5 w-5 text-gray-400" />
                  <span className="text-gray-600 dark:text-gray-300">Click to upload {doc.name.toLowerCase()}</span>
                </label>
              </div>
            ) : (
              <div className="flex items-center gap-2 text-sm">
                <FileText className="h-4 w-4 text-gray-500" />
                <span className="text-gray-700 dark:text-gray-200">{doc.file.name}</span>
                <span className="text-gray-500">({(doc.file.size / 1024 / 1024).toFixed(2)} MB)</span>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Verification Status */}
      {verificationStatus !== 'pending' && (
        <div className="mb-6">
          <h4 className="font-medium text-gray-800 dark:text-white mb-3">Verification Status</h4>
          <div className={`p-4 rounded-xl ${
            verificationStatus === 'verified'
              ? 'bg-green-50 dark:bg-green-900/20 border border-green-200'
              : verificationStatus === 'rejected'
              ? 'bg-red-50 dark:bg-red-900/20 border border-red-200'
              : verificationStatus === 'error'
              ? 'bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200'
              : 'bg-blue-50 dark:bg-blue-900/20 border border-blue-200'
          }`}>
            <div className="flex items-start gap-3">
              {verificationStatus === 'verified' && <CheckCircle className="h-5 w-5 text-green-600 mt-0.5" />}
              {verificationStatus === 'rejected' && <XCircle className="h-5 w-5 text-red-600 mt-0.5" />}
              {verificationStatus === 'error' && <AlertTriangle className="h-5 w-5 text-yellow-600 mt-0.5" />}
              {(verificationStatus === 'submitting') && <Clock className="h-5 w-5 text-blue-600 mt-0.5" />}

              <div className="flex-1">
                <p className="font-medium text-gray-800 dark:text-white">
                  {verificationStatus === 'verified' && 'Verification Successful'}
                  {verificationStatus === 'rejected' && 'Verification Failed'}
                  {verificationStatus === 'error' && 'Verification Error'}
                  {verificationStatus === 'submitting' && 'Submitting for Verification...'}
                </p>
                {lguResponse && (
                  <p className="text-sm text-gray-600 dark:text-gray-300 mt-1">
                    {lguResponse.message}
                  </p>
                )}
                {lguResponse && lguResponse.verifiedBy && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-2">
                    Verified by: {lguResponse.verifiedBy} on {new Date(lguResponse.verifiedAt).toLocaleDateString()}
                  </p>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Submit Button */}
      <div className="flex justify-end">
        <button
          onClick={submitForVerification}
          disabled={isSubmitting || verificationStatus === 'verified'}
          className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-colors ${
            isSubmitting || verificationStatus === 'verified'
              ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
              : 'bg-mountain-green text-white hover:bg-mountain-green-light'
          }`}
        >
          {isSubmitting ? (
            <>
              <Clock className="h-5 w-5 animate-spin" />
              Submitting...
            </>
          ) : verificationStatus === 'verified' ? (
            <>
              <CheckCircle className="h-5 w-5" />
              Verified
            </>
          ) : (
            <>
              <Shield className="h-5 w-5" />
              Submit for Verification
            </>
          )}
        </button>
      </div>

      {/* Guidelines */}
      <div className="mt-6 bg-blue-50 dark:bg-blue-900/20 rounded-xl p-4">
        <div className="flex items-start gap-3">
          <AlertTriangle className="h-5 w-5 text-blue-600 mt-0.5" />
          <div>
            <h5 className="font-medium text-blue-900 dark:text-blue-100 mb-2">Verification Guidelines</h5>
            <ul className="text-sm text-blue-800 dark:text-blue-200 space-y-1">
              <li>• All documents must be clear, legible, and in PDF or image format</li>
              <li>• Business permits and IDs must be current and not expired</li>
              <li>• Property ownership documents must match the property details</li>
              <li>• Verification process may take 2-5 business days</li>
              <li>• All verifications are recorded on the BlockVerify blockchain</li>
            </ul>
          </div>
        </div>
      </div>
    </motion.div>
  );
};

export default PartnerVerification;
